import numpy as np

def make_input(agent_col, ball_row, ball_col):
    x = np.zeros(500)
    # wall border in channel 3
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                x[(r*10 + c)*5 + 3] = 1.0
    # agent at row 8, col agent_col, channel 0
    x[(8*10 + agent_col)*5 + 0] = 1.0
    # moving object at ball_row, ball_col, channel 1
    x[(ball_row*10 + ball_col)*5 + 1] = 1.0
    # channel 4 = 0, channel 2 = 0
    return x

