import numpy as np

def obs(agent=None, moving=None, reward=None, obstacle=None):
    x = np.zeros((10, 10, 5), dtype=float)
    # wall border is always in channel 3
    x[0, :, 3] = 1
    x[9, :, 3] = 1
    x[:, 0, 3] = 1
    x[:, 9, 3] = 1
    if agent is not None:
        x[agent[0], agent[1], 0] = 1
    if moving is not None:
        for r, c in moving:
            x[r, c, 1] = 1
    if reward is not None:
        for r, c in reward:
            x[r, c, 2] = 1
    if obstacle is not None:
        for r, c in obstacle:
            if 0 < r < 9 and 0 < c < 9:
                x[r, c, 3] = 1
    return x.reshape(-1)

conditions = [
    ("base",            obs((8, 4))),
    ("reward_top",      obs((8, 4), reward=[(1, 4)])),
    ("move_above",      obs((8, 4), moving=[(7, 4)])),
    ("move_above_left", obs((8, 4), moving=[(7, 3)])),
    ("move_two_above",  obs((8, 4), moving=[(6, 4)])),
    ("obst_above",      obs((8, 4), obstacle=[(7, 4)])),
    ("obst_two_above",  obs((8, 4), obstacle=[(6, 4)])),
    ("reward+move",     obs((8, 4), reward=[(1, 4)], moving=[(7, 4)])),
]

X = np.stack([c[1] for c in conditions])
logits = forward(X)
probs = np.exp(logits - logits.max(axis=1, keepdims=True))
probs /= probs.sum(axis=1, keepdims=True)

for (name, _), p in zip(conditions, probs):
    print(f"{name:16s} argmax={p.argmax()} probs={np.round(p, 3)}")
